#!/usr/bin/env bash
set -euo pipefail
umask 077
VERSION="1.0.0-rc3"
EXPECTED_SHA256="f14cad4cd4f5379cd64d93e9a316c45fb2c4bf9067ae51274feaf69430d9aa2a"
usage() {
  cat <<'HADS_NEXT_USAGE'
HADS Next 1.0.0-rc3 — samostatná vývojová aplikace, nikoli produkční RC.
Použití:
  bash HADS_Next_install_1.0.0-rc3.sh --verify
  bash HADS_Next_install_1.0.0-rc3.sh --extract-only /absolutni/novy-adresar
  bash HADS_Next_install_1.0.0-rc3.sh --install-dev
  bash HADS_Next_install_1.0.0-rc3.sh --upgrade-rc2
Nová instalace přidá local_hads_next_practical. Výslovný --upgrade-rc2 aktualizuje jen ověřený zastavený Next RC2; zachová /data a vyžádá nativní částečnou zálohu. Starý Hermes 2.0.0-rc3 se nemění.
Původní Hermes je součástí balíčku. AI i vlastní testovací opravný katalog vyžadují výslovný souhlas. Obecné produkční zápisy jsou zakázané. Živá HAOS přejímka čeká.
HADS_NEXT_USAGE
}
MODE="${1:-}"
case "$MODE" in
  --help) [ "$#" = 1 ] || exit 2; usage; exit 0 ;;
  --verify|--install-dev|--upgrade-rc2) [ "$#" = 1 ] || { usage; exit 2; } ;;
  --extract-only) [ "$#" = 2 ] || { usage; exit 2; } ;;
  *) usage; exit 2 ;;
esac
command -v python3 >/dev/null || { echo 'Chybí python3 v terminálové aplikaci. Podrobnosti jsou v návodu DOCS.md.' >&2; exit 1; }
command -v base64 >/dev/null || { echo 'Chybí base64.' >&2; exit 1; }
STAGING="$(mktemp -d /tmp/hads-next-install.XXXXXX)"
cleanup() {
  case "$STAGING" in /tmp/hads-next-install.*) rm -rf -- "$STAGING" ;; esac
}
trap cleanup EXIT
base64 -d > "$STAGING/payload.tar.gz" <<'HADS_NEXT_PAYLOAD'
